import{_ as a,o,c as s,a6 as r}from"./chunks/framework.DNkVJs23.js";const u=JSON.parse('{"title":"Política de privacidade","description":"Política de privacidade — Sapphire Star Codex","frontmatter":{"description":"Política de privacidade — Sapphire Star Codex","head":[["link",{"rel":"canonical","href":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/privacy/"}],["meta",{"property":"og:url","content":"https://eurekaffeine.github.io/sapphire-star-codex/pt-br/privacy/"}],["meta",{"property":"og:title","content":"Política de privacidade | Sapphire Star Codex"}],["meta",{"property":"og:description","content":"Política de privacidade — Sapphire Star Codex"}]]},"headers":[],"relativePath":"pt-br/privacy/index.md","filePath":"pt-br/privacy/index.md"}'),i={name:"pt-br/privacy/index.md"};function t(n,e,d,c,p,l){return o(),s("div",null,[...e[0]||(e[0]=[r('<h1 id="politica-de-privacidade" tabindex="-1">Política de privacidade <a class="header-anchor" href="#politica-de-privacidade" aria-label="Permalink to &quot;Política de privacidade&quot;">​</a></h1><p>Vigência: 31 de outubro de 2026. Última atualização do texto original: 10 de novembro de 2026. Tradução: 14 de novembro de 2026.</p><p>Esta política abrange os apps iOS, Android e HarmonyOS de Sapphire Star Codex e este site. Desenvolvedor: <strong>eurekaffeine (刘耀晨)</strong>. Contato: <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a>. Os recursos variam conforme a plataforma; não é necessário criar uma conta.</p><h2 id="dados-locais" tabindex="-1">Dados locais <a class="header-anchor" href="#dados-locais" aria-label="Permalink to &quot;Dados locais&quot;">​</a></h2><p>O app guarda no dispositivo preferências de jogo, idioma e aparência, histórico de busca e estado de navegação, favoritos, conjuntos salvos e seus nomes, além de inventários de decorações, talismãs e armaduras. Esses dados viabilizam os recursos e não são enviados ao desenvolvedor. O desenvolvedor não mantém contas nem sincronização na nuvem.</p><h2 id="permissoes-e-coleta-automatica" tabindex="-1">Permissões e coleta automática <a class="header-anchor" href="#permissoes-e-coleta-automatica" aria-label="Permalink to &quot;Permissões e coleta automática&quot;">​</a></h2><p>O app não integra SDKs de publicidade, rastreamento, estatísticas de uso ou envio automático de falhas. Os recursos atuais não exigem contatos, localização, câmera, microfone ou fotos e não coletam identificadores de publicidade. O sistema e as lojas podem processar dados de instalação ou diagnóstico segundo suas regras. Diagnósticos fornecidos ao desenvolvedor são usados apenas para resolver problemas.</p><h2 id="contato-e-servicos-externos" tabindex="-1">Contato e serviços externos <a class="header-anchor" href="#contato-e-servicos-externos" aria-label="Permalink to &quot;Contato e serviços externos&quot;">​</a></h2><p>Ao enviar um email voluntário, o desenvolvedor recebe endereço, mensagem e anexos para responder, investigar problemas e atender pedidos de privacidade, não para marketing. Envie somente o necessário. O Gmail processa emails conforme a <a href="https://policies.google.com/privacy" target="_blank" rel="noreferrer">política do Google</a>.</p><p>O GitHub Pages hospeda este site e pode receber endereço IP e dados técnicos do navegador; consulte a <a href="https://docs.github.com/en/site-policy/privacy-policies/github-general-privacy-statement" target="_blank" rel="noreferrer">declaração do GitHub</a>. Não são adicionados análise de visitas, cookies publicitários ou pixels de rastreamento. A busca ocorre no navegador, que pode guardar preferências. Serviços externos aplicam suas próprias políticas e podem processar dados fora do seu país.</p><h2 id="contribuicoes-e-backups" tabindex="-1">Contribuições e backups <a class="header-anchor" href="#contribuicoes-e-backups" aria-label="Permalink to &quot;Contribuições e backups&quot;">​</a></h2><p>Alipay ou WeChat Pay processa contribuições segundo suas condições. O site só mostra códigos estáticos, sem SDK de pagamento nem recebimento de credenciais. O desenvolvedor pode ver dados apresentados ao recebedor, como valor, data, nome exibido e observação, para conferir contribuições e resolver problemas. A retenção segue as regras da plataforma e as obrigações aplicáveis. Conforme suas configurações, os dados do app podem entrar em backups locais ou na nuvem; o desenvolvedor não consegue ler ou excluir esses backups.</p><h2 id="compartilhamento-retencao-e-exclusao" tabindex="-1">Compartilhamento, retenção e exclusão <a class="header-anchor" href="#compartilhamento-retencao-e-exclusao" aria-label="Permalink to &quot;Compartilhamento, retenção e exclusão&quot;">​</a></h2><p>O desenvolvedor não vende ou aluga dados pessoais nem os compartilha para publicidade. O fornecedor indicado processa os emails. Informações efetivamente mantidas podem ser fornecidas por obrigação legal ou pedido explícito.</p><p>Apague dados locais pelas funções do app ou configurações do sistema. Desinstalações que preservam dados não os removem; gerencie backups separadamente, pois eles podem restaurá-los. Preferências do site ficam até a exclusão ou limpeza automática do navegador. Mensagens são guardadas apenas pelo tempo necessário ao atendimento, acompanhamento ou obrigações legais. Provedores gerenciam seus próprios registros e backups. Entre em contato para acessar, corrigir ou pedir exclusão do que enviou, respeitadas as obrigações de retenção. O desenvolvedor não acessa remotamente dados que permanecem apenas no dispositivo.</p><h2 id="seguranca-menores-e-atualizacoes" tabindex="-1">Segurança, menores e atualizações <a class="header-anchor" href="#seguranca-menores-e-atualizacoes" aria-label="Permalink to &quot;Segurança, menores e atualizações&quot;">​</a></h2><p>Os mecanismos do sistema protegem os dados locais. O site usa HTTPS. O acesso a mensagens se limita ao suporte e à privacidade, com as proteções do provedor de email. O app não pede perfis pessoais ou data de nascimento e não coleta intencionalmente dados de crianças. Responsáveis podem solicitar a exclusão de informações enviadas por uma criança.</p><p>A política e sua data mudam quando as práticas mudam. Alterações importantes são anunciadas no site ou nas atualizações do app. Permissões e consentimentos necessários para novos recursos são solicitados separadamente; esta política não os substitui.</p><p><strong>eurekaffeine (刘耀晨)</strong> — <a href="mailto:eurekaffeine.work@gmail.com" target="_blank" rel="noreferrer">eurekaffeine.work@gmail.com</a></p>',19)])])}const v=a(i,[["render",t]]);export{u as __pageData,v as default};
